<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowLeftOutlined,ReloadOutlined,CheckCircleFilled,ExclamationCircleFilled,LockOutlined,PlusOutlined,FilePdfOutlined,ProfileOutlined,FolderOpenOutlined,FileTextOutlined,ExperimentOutlined,WarningOutlined,AuditOutlined} from '@ant-design/icons-vue'
import {api,http} from '../../api/http'
import {useControlledRequest} from '../../api/controlled'
import {useAuthStore} from '../../stores/auth'
import ReadReference from '../master/ReadReference.vue'
import IncomingFacts from './IncomingFacts.vue'
import {qaEvidenceLabel} from './qaEvidencePresentation'
import {canDecide,signingTarget,releaseCommand,gateLabels,type FinishedReview,type BatchArchive,type PdfManifest} from './finishedReleaseModel'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),request=useControlledRequest(),{busy,error,conflict}=request
const review=ref<FinishedReview|null>(null),archive=ref<BatchArchive|null>(null),decision=ref<'RELEASED'|'REJECTED'|null>(null),reason=ref(''),lot=ref(''),predecessor=ref(''),password=ref(''),signatureOpen=ref(false),pdfOpen=ref(false),pdfReason=ref(''),kind=ref<'REVIEW_COPY'|'FINAL'>('REVIEW_COPY')
const lotNames=ref<Record<string,string>>({})
function lotLabel(id:string){return lotNames.value[id]??`关联成品批次 ${Math.max(0,review.value?.finishedLots.indexOf(id)??0)+1}`}
function decisionLabel(id:string|null){if(!id)return '—';const d=archive.value?.decisions.find(d=>d.id===id);return d?`${d.decisionAt?.replace('T',' ').slice(0,16)??''} ${d.decision==='RELEASED'?'放行':'拒绝'}`:'关联决定证据暂不可读取'}
const work=computed(()=>route.meta.mode==='release'),latestDecision=computed(()=>archive.value?.decisions[archive.value.decisions.length-1]),finalReady=computed(()=>['QA_RELEASED','REJECTED'].includes(review.value?.status??'')),ready=computed(()=>review.value?.gates.filter(g=>g.passed).length??0)
async function load(){busy.value=true;request.clear();try{review.value=await api({url:`/qa/batches/${route.params.id}/review-model`});lot.value=review.value!.finishedLots[0]??'';archive.value=auth.can('ebr:form:view')?await api({url:`/main-batches/${route.params.id}/ebr`}):null;decision.value=null;signatureOpen.value=false;predecessor.value=latestDecision.value?.id??'';lotNames.value={};if(auth.can('wms:inventory:view'))await Promise.all(review.value!.finishedLots.map(async id=>{try{const row=await api<{lotNo:string}>({url:`/wms/material-lots/${id}`});if(row.lotNo)lotNames.value[id]=row.lotNo}catch{/* Keep a non-technical reference label when lookup cannot be read. */}}))}catch(e){await request.failure(e)}finally{busy.value=false}}
function choose(value:'RELEASED'|'REJECTED'){decision.value=value;reason.value='';password.value='';predecessor.value=latestDecision.value?.id??''}
function prepare(){if(!review.value||!decision.value)return;try{releaseCommand(review.value,decision.value,lot.value,reason.value,'check',predecessor.value||null);signatureOpen.value=true}catch(e){void request.failure(e)}}
async function submit(){if(!review.value||!decision.value)return;busy.value=true;try{if(!password.value)throw Error('请输入签名密码');const token=await api<{reauthToken:string}>({url:'/auth/reauth',method:'POST',data:{...signingTarget(review.value,decision.value),credential:password.value}});const body=releaseCommand(review.value,decision.value,lot.value,reason.value,token.reauthToken,predecessor.value||null);await request.mutate('/release-decisions','POST',body,review.value.versionNo);await load()}catch(e){await request.failure(e);if(conflict.value)signatureOpen.value=false}finally{password.value='';busy.value=false}}
async function generate(){if(!review.value)return;busy.value=true;try{if(!pdfReason.value.trim())throw Error('请填写归档原因');await request.mutate(`/main-batches/${route.params.id}/ebr/pdf`,'POST',{versionNo:review.value.versionNo,archiveKind:kind.value,reason:pdfReason.value.trim()},review.value.versionNo);pdfOpen.value=false;await load()}catch(e){await request.failure(e)}finally{busy.value=false}}
async function download(item:PdfManifest){busy.value=true;try{const current=await api<PdfManifest>({url:`/main-batches/${route.params.id}/ebr/pdf/${item.id}`});const response=await http.get<ArrayBuffer>(`/attachments/${current.fileId}/content`,{responseType:'arraybuffer'});const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',response.data))).map(v=>v.toString(16).padStart(2,'0')).join('');if(hash!==current.fileHash)throw Error('归档文件校验失败，请联系管理员');const url=URL.createObjectURL(new Blob([response.data],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=`eBR-${route.params.id}-${current.archiveKind}-v${current.generationVersion}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){await request.failure(e)}finally{busy.value=false}}
const histories=computed(()=>archive.value?[{title:'eBR 表单与原始修订',value:archive.value.forms},{title:'IPC / QC 原始结果与复核',value:archive.value.qcTests},{title:'平衡结果与调查',value:archive.value.balances},{title:'偏差与质量调查',value:archive.value.deviations},{title:'工艺快照',value:archive.value.processSnapshot?[archive.value.processSnapshot]:[]},{title:'工序执行',value:archive.value.operations},{title:'投料记录',value:archive.value.charges},{title:'产量、损耗与冲销',value:archive.value.quantityEvents},{title:'物料谱系',value:archive.value.genealogy},{title:'电子签名证据',value:archive.value.signatures}]:[])
const evidenceTab=ref('全部'),selectedEvidence=ref<{title:string;value:Record<string,unknown>[]} | null>(null)
const evidenceGroups=computed(()=>histories.value.map((item,index)=>({...item,group:index===0||index===4||index===5?'生产执行':index===1?'质量检验':index===2||index===6||index===7||index===8?'物料':index===3?'偏差':'电子签名'})).concat(archive.value?[{title:'成品仓库接收',value:archive.value.finishedReceiving??[],group:'物料'},{title:'成品请验、取样及报告',value:archive.value.finishedQuality?.requests??[],group:'质量检验'},{title:'历次 QA 质量决定',value:archive.value.decisions.map(d=>({...d})),group:'质量检验'}]:[]))
const evidenceTabs=computed(()=>['全部','生产执行','质量检验','物料','偏差','电子签名'].map(title=>({title,count:evidenceGroups.value.filter(item=>title==='全部'||item.group===title).reduce((sum,item)=>sum+item.value.length,0)})))
const visibleEvidence=computed(()=>evidenceGroups.value.filter(item=>evidenceTab.value==='全部'||item.group===evidenceTab.value))
const progress=computed(()=>review.value?.gates.length?Math.round(ready.value/review.value.gates.length*100):0)
const hasFinal=computed(()=>archive.value?.pdfManifests.some(item=>item.archiveKind==='FINAL')??false)
const statusLabel=computed(()=>({PENDING_QA:'待 QA 审核',QA_RELEASED:'已 QA 放行',REJECTED:'已拒绝'}[review.value?.status??'']??review.value?.status))
function showGate(gate:FinishedReview['gates'][number]){selectedEvidence.value={title:gateLabels[gate.code]??gate.code,value:[{gateCode:gate.code,passed:gate.passed,blockingCodes:gate.blockingCodes,evidenceIds:gate.evidenceIds}]}}
watch(()=>route.fullPath,()=>{archive.value=null;selectedEvidence.value=null;evidenceTab.value='全部';void load()},{immediate:true})
</script>
<!-- UI Template: T6 Decision Workbench. PDF is post-decision evidence, not a Release Gate. -->
<template><main data-ui-template="T6" class="admin-page master-page qa-page">
<header class="admin-page-header qa-header"><div><h1>{{work?'QA 批放行审核':'QA 批审详情'}}</h1><p>核对批次质量证据与电子签名后执行质量决定。</p></div><a-space wrap><a-button @click="router.push('/production/batches/'+route.params.id)"><ArrowLeftOutlined/> 返回生产批</a-button><a-button :loading="busy" @click="load"><ReloadOutlined/> 刷新证据</a-button><a-button v-if="!work&&auth.can('qa:release')" type="primary" @click="router.push('/qa/batches/'+route.params.id+'/release')">放行决定</a-button></a-space>
<div v-if="review" class="qa-banner"><div class="batch-heading"><strong>{{review.batchNo}}</strong><a-tag :color="review.status==='QA_RELEASED'?'green':'orange'">{{statusLabel}}</a-tag><span v-if="archive">产品：<ReadReference field="productId" :value="archive.batch.productId" fallback="产品信息暂不可读取"/></span><span v-if="archive">计划数量：{{archive.batch.plannedQty}}<ReadReference field="unitId" :value="archive.batch.unitId" fallback="单位信息暂不可读取"/></span></div><div class="gate-progress"><div><strong>{{ready}} / {{review.gates.length}}</strong><span>放行前 Gate 已满足</span></div><a-progress :percent="progress" stroke-color="#4cbd83" size="small"/></div></div></header>
<a-alert v-if="error" type="error" :message="error" show-icon class="form-section"/><a-alert v-if="conflict" type="warning" message="批次证据已变化，请刷新后重新核对并签名。" class="form-section"/>
<div v-if="review" class="qa-columns"><div class="qa-gate-column"><a-card title="放行 Gate Checklist" class="qa-checklist"><p class="section-hint">检查所有关键项；检验合格后仍须独立 QA 放行。</p><div class="gate-grid"><article v-for="(gate,index) in review.gates" :key="gate.code" class="gate-card" :class="{'gate-warning':!gate.passed}"><div class="gate-number"><CheckCircleFilled v-if="gate.passed" class="pass"/><ExclamationCircleFilled v-else class="blocked"/><span>{{index+1}}</span></div><div class="gate-description"><strong>{{gateLabels[gate.code]??gate.code}}</strong><p>{{gate.passed?'检查通过':'检查未通过'}}</p><p v-for="code in gate.blockingCodes" :key="code" class="error">{{code}}</p></div><a-tag :color="gate.passed?'green':'orange'"><CheckCircleFilled v-if="gate.passed"/><ExclamationCircleFilled v-else/> {{gate.passed?'已通过':'未通过'}}</a-tag><a-button size="small" @click="showGate(gate)">查看</a-button></article>
</div><a-alert v-if="review.blockingCodes.length" type="warning" :message="review.blockingCodes.join('、')" show-icon class="blocking-summary"/></a-card>
</div>
<div class="qa-side"><a-card class="batch-summary"><template #title><ProfileOutlined class="section-icon"/> 批次摘要</template><a-descriptions :column="1" size="small"><a-descriptions-item label="正式批号">{{review.batchNo}}</a-descriptions-item><a-descriptions-item label="当前状态"><a-tag :color="review.status==='QA_RELEASED'?'green':'orange'">{{statusLabel}}</a-tag></a-descriptions-item><a-descriptions-item v-if="archive" label="产品"><ReadReference field="productId" :value="archive.batch.productId" fallback="产品信息暂不可读取"/></a-descriptions-item><a-descriptions-item v-if="archive" label="计划数量">{{archive.batch.plannedQty}}<ReadReference field="unitId" :value="archive.batch.unitId" fallback="单位信息暂不可读取"/></a-descriptions-item><a-descriptions-item label="成品批次">{{review.finishedLots.map(lotLabel).join('、')||'尚未形成'}}</a-descriptions-item><a-descriptions-item v-if="archive?.batch.completedAt" label="生产完成时间">{{archive.batch.completedAt}}</a-descriptions-item></a-descriptions></a-card>
<a-card title="允许动作"><p class="action-hint">{{review.allowedActions.length?'质量决定需核对证据并完成电子签名。':'当前状态没有允许的质量决定。'}}</p><div class="release-actions" v-if="work&&auth.can('qa:release')"><a-button v-if="canDecide(review,'REJECTED')" :disabled="busy" @click="choose('REJECTED')">拒绝</a-button><a-button v-if="canDecide(review,'RELEASED')" type="primary" aria-label="签名并放行" :disabled="busy" @click="choose('RELEASED')"><LockOutlined aria-hidden="true"/> 签名并放行</a-button></div><p v-else class="section-hint">请进入放行工作页执行授权质量决定。</p></a-card></div></div>
<a-card v-if="decision&&review" :title="decision==='RELEASED'?'物料放行决定':'物料拒绝决定'" class="form-section"><form @submit.prevent="prepare"><div class="master-form"><label><span class="form-field-label">成品批次</span><select v-model="lot" aria-label="成品批次" class="master-native-input" :disabled="busy"><option v-for="id in review.finishedLots" :key="id" :value="id">{{lotLabel(id)}}</option></select></label><label v-if="finalReady"><span class="form-field-label">前序决定</span><select v-model="predecessor" aria-label="前序决定" class="master-native-input" required :disabled="busy"><option v-for="item in archive?.decisions??[]" :key="item.id" :value="item.id">{{decisionLabel(item.id)}}</option></select></label><label><span class="form-field-label">操作原因</span><textarea v-model="reason" aria-label="操作原因" class="master-native-input" required maxlength="1000" :disabled="busy"/></label></div><a-space class="command-buttons"><a-button html-type="submit" type="primary" :disabled="busy||conflict">核对并签名</a-button><a-button @click="decision=null">取消</a-button></a-space></form></a-card>
<div v-if="archive" class="qa-bottom"><a-card title="eBR 归档 PDF 版本历史" class="archive-history"><template #extra><a-button v-if="auth.can('ebr:pdf:generate')" :disabled="busy" @click="pdfOpen=true;kind=finalReady?'FINAL':'REVIEW_COPY';pdfReason=''"><PlusOutlined/> 生成 PDF 归档</a-button></template><section class="post-decision-archive" aria-label="QA 决定后归档步骤"><h3>QA 决定后归档步骤</h3><p class="section-hint">以下为质量决定后的归档工作，不计入放行前 Gate。</p><article class="archive-step"><div class="archive-icon"><CheckCircleFilled v-if="hasFinal" class="pass"/><FilePdfOutlined v-else/></div><div class="gate-description"><strong>最终 eBR PDF</strong><p>{{hasFinal?'已有不可变最终归档':'有效 QA 质量决定后生成；审核副本不等于最终归档'}}</p></div><a-tag :color="hasFinal?'green':'default'">{{hasFinal?'已归档':finalReady?'待归档':'QA 决定后生成'}}</a-tag></article></section><a-table size="small" :columns="[{title:'版本',dataIndex:'generationVersion',width:40},{title:'生成时间',dataIndex:'generatedAt',width:135},{title:'归档类型',dataIndex:'archiveKind',width:90},{title:'QA 决定',dataIndex:'releaseDecisionId',width:70},{title:'生成者',dataIndex:'generatedBy',width:64},{title:'操作',key:'download',width:110,fixed:'right'}]" :data-source="archive.pdfManifests" row-key="id" :scroll="{x:604}" :pagination="false"><template #bodyCell="{record,column}"><a-button v-if="column.key==='download'" type="link" :disabled="busy" @click="download(record)">下载并校验</a-button><a-tag v-else-if="column.dataIndex==='archiveKind'" :color="record.archiveKind==='FINAL'?'green':'orange'">{{record.archiveKind==='FINAL'?'最终归档':'审核副本'}}</a-tag><span v-else-if="column.dataIndex==='generationVersion'">V{{record.generationVersion}}</span><span v-else-if="column.dataIndex==='generatedAt'" :title="record.generatedAt">{{record.generatedAt.replace('T',' ').slice(0,16)}}</span><span v-else-if="column.dataIndex==='releaseDecisionId'">{{decisionLabel(record.releaseDecisionId)}}</span><ReadReference v-else-if="column.dataIndex==='generatedBy'" field="userId" :value="record.generatedBy" fallback="人员信息暂不可读取"/></template></a-table><details class="archive-technical"><summary>归档校验与引用证据</summary><IncomingFacts :value="{recordDigest:archive.recordDigest,pdfManifests:archive.pdfManifests}" :label-formatter="qaEvidenceLabel"/></details></a-card>
<a-card class="evidence-directory"><template #title><FolderOpenOutlined class="section-icon"/> 批记录证据目录</template><div class="evidence-tabs" role="tablist" aria-label="证据类别"><button v-for="tab in evidenceTabs" :key="tab.title" role="tab" :aria-selected="evidenceTab===tab.title" :class="{active:evidenceTab===tab.title}" @click="evidenceTab=tab.title">{{tab.title}}（{{tab.count}}）</button></div><a-table size="small" :columns="[{title:'类别',dataIndex:'title'},{title:'数量',key:'count',width:60},{title:'操作',key:'view',width:70}]" :data-source="visibleEvidence" row-key="title" :pagination="{pageSize:5,size:'small',hideOnSinglePage:true,showSizeChanger:false}"><template #bodyCell="{record,column}"><button v-if="column.dataIndex==='title'" class="evidence-link" @click="selectedEvidence={title:record.title,value:record.value}"><component :is="record.group==='质量检验'?ExperimentOutlined:record.group==='偏差'?WarningOutlined:record.group==='电子签名'?AuditOutlined:FileTextOutlined" class="evidence-icon"/> {{record.title}}（{{record.value.length}}）</button><span v-else-if="column.key==='count'">{{record.value.length}}</span><a-button v-else-if="column.key==='view'" type="link" @click="selectedEvidence={title:record.title,value:record.value}">查看</a-button></template></a-table></a-card></div>
<a-drawer class="qa-evidence-drawer" :open="!!selectedEvidence" :title="selectedEvidence?.title==='eBR 表单与原始修订'?'电子批记录表单与原始修订':selectedEvidence?.title" :width="560" @close="selectedEvidence=null"><p v-if="!selectedEvidence?.value.length">暂无记录</p><IncomingFacts v-for="(fact,index) in selectedEvidence?.value" :key="index" :value="fact" :label-formatter="qaEvidenceLabel"/></a-drawer>
<a-modal v-model:open="signatureOpen" title="电子签名确认" ok-text="签名并提交" cancel-text="取消" :confirm-loading="busy" @ok="submit" @cancel="password=''"><p>质量决定：{{decision==='RELEASED'?'放行':'拒绝'}}，绑定当前核对的生产批记录。</p><div class="master-form" style="grid-template-columns:1fr"><label><span class="form-field-label">签名密码</span><input v-model="password" class="master-native-input" type="password" aria-label="签名密码" autocomplete="current-password" @keydown.enter.prevent="submit"/></label></div></a-modal>
<a-modal v-model:open="pdfOpen" title="生成 eBR PDF" ok-text="生成归档" cancel-text="取消" :confirm-loading="busy" @ok="generate"><div class="master-form" style="grid-template-columns:1fr"><label><span class="form-field-label">归档类型</span><select v-model="kind" aria-label="归档类型" class="master-native-input"><option value="REVIEW_COPY">审核副本</option><option v-if="finalReady" value="FINAL">最终归档</option></select></label><label><span class="form-field-label">归档原因</span><textarea v-model="pdfReason" aria-label="归档原因" class="master-native-input" maxlength="1000" required/></label></div><p>相同证据复用既有归档；证据变化生成新版本并保留历史。</p></a-modal></main></template>
<style scoped>
