b45c13}.gate-card>.ant-tag{flex-shrink:0;margin:0;font-size:11px;border:0}.gate-card>.ant-btn{flex-shrink:0;font-size:11px;height:26px}.qa-side{display:grid;gap:14px}.qa-gate-column{display:grid;gap:16px;min-width:0}.archive-step{display:flex;align-items:center;gap:12px}.archive-icon{font-size:20px;color:var(--mes-ui-secondary)}.archive-step>.ant-tag{flex-shrink:0;margin:0}.archive-step .gate-description p{font-size:12px;line-height:18px}.qa-page :deep(.ant-descriptions .ant-descriptions-item){padding:0 0 5px}.qa-page :deep(.ant-descriptions-item-container){border-bottom:1px solid #f1f4f8;padding-bottom:3px}.qa-page :deep(.ant-descriptions-item-label){width:110px;color:#65748b;font-size:12px}.qa-page :deep(.ant-descriptions-item-content){font-size:12px;color:#24344e;overflow-wrap:anywhere}.action-hint{background:#fff8e9;color:#a86c18;border:1px solid #fae7c7;border-radius:4px;padding:8px 10px;margin:0 0 10px;font-size:12px}.release-actions{display:flex;gap:12px}.release-actions>.ant-btn{flex:1}.blocking-summary,.command-buttons{margin-top:12px}.qa-bottom{display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:start}.digest{overflow-wrap:anywhere;font:10px ui-monospace,Consolas,monospace;color:#8290a5;margin:12px 0 0}.hash{font:11px ui-monospace,Consolas,monospace}.evidence-tabs{display:flex;gap:4px;overflow-x:auto;margin:0 0 10px}.evidence-tabs button{border:0;border-bottom:2px solid transparent;background:#f6f8fc;color:#65748b;white-space:nowrap;padding:8px 9px;font:inherit;font-size:11px;cursor:pointer}.evidence-tabs button.active{border-bottom-color:#2c5cdc;color:#2c5cdc;background:#edf3ff}.evidence-link{border:0;padding:0;background:none;color:#24344e;text-align:left;cursor:pointer;font:inherit;font-size:12px}.evidence-link:hover{color:#2c5cdc}.evidence-link:focus-visible,.evidence-tabs button:focus-visible{outline:2px solid #2c5cdc;outline-offset:2px}.qa-page :deep(.ant-table-thead>tr>th){font-size:11px;padding:9px 8px}.qa-page :deep(.ant-table-tbody>tr